 *
 * @property Evento $idEvento
 * @property DadosPessoais $cpfDadospessoais
 * @property Atividade[] $atividades
 */
abstract class BaseInscricao extends GxActiveRecord {


	public static function model($className=__CLASS__) {
		return parent::model($className);
	}

	public function tableName() {
		return 'Inscricao';
	}

	public static function label($n = 1) {
		return Yii::t('app', 'Inscrição|Inscrições',$n);
	}

	public static function representingColumn() {
		return 'id';
	}

	public function rules() {
		return array(
			array('id_evento,cpf_dadospessoais', 'required'),
			array('id_evento,cpf_dadospessoais', 'numerical', 'integerOnly'=>true),
			array('cpf_dadospessoais', 'exist', 'attributeName'=>'cpf','className'=>'DadosPessoais','skipOnError'=>true),
			array('id, id_evento, cpf_dadospessoais', 'safe', 'on'=>'search'),
			array('id_evento', 'checkPeriodo','skipOnError'=>true),
			array('id', 'checkDupla','skipOnError'=>true),
			array('atividades', 'checkMultihorario','skipOnError'=>true),
			array('atividades', 'checkNaoEletiva','skipOnError'=>true),
		);
	}

	public function checkPeriodo($atribbute)
	{
		if ($this->hasErrors())
			return;
		//admins podem realizar inscrições em eventos que não iniciaram ou que já encerarram.
		if(Yii::app()->user->role=='Admin' || Yii::app()->user->role=='Coordenadores') {
			return;
		}
		$result=Evento::model()->findAllAttributes(null, true,"(datainscricaof + interval '23 hours') >= NOW() and datainscricaoi <= NOW() AND id = :param1",
			array(":param1"=>(int)$this->id_evento));
		if ($result==null)
		{
			$this->addError($atribbute, 'Evento Inválido');
		}
	}

	//verifica se no momento do insert o usuário selecionou todas as atividades eletivas possíveis que são aquelas que acontecem no momento
	// do cadastro e doravante.
	// Durante o update verifica se o mesmo desmarcou alguma atividade que foi selecionado durante a inscrição
	public function checkNaoEletiva($atribbute)
	{
		if ($this->hasErrors())
			return;
		//se o usuário não selecionou nenhuma atividade, seja na inscrição ou no update
		if ( $this->atividades==null) {
			$this->addError($atribbute, 'Você não marcou nenhuma atividade');
			return;
		}

		if(Yii::app()->user->role=='Admin' || Yii::app()->user->role=='Coordenadores')
			$time="";
		else
			$time="AND (data+horafinal+'12:00:00') >= now()";


		if ( Yii::app()->controller->action->id=='update' )
			//nao eletivas selecionadas durante o processo de inscrição (update)
			$naoeletivas=Inscricaoatividade::model()->findAllAttributes(null,true,
				"id_inscricao=:param1 AND id_atividade in (select id from atividade where eletivo=false and id_evento=:param2)",
				array(":param1"=>$this->id,"param2"=>$this->id_evento));
		else
			//não eletivas existentes neste momento com vagas disponíveis( create)
			$naoeletivas=Atividade::model()->findAllAttributes(
				null,true,"eletivo = false and vagasdisponiveis > 0 and id_evento=:param1 $time",
				array(":param1"=>$this->id_evento));


		//verifica quantas atividades nao eletivas foram deselecionadas.
		$countnoteletiva=0;
		$selectedAtivs=$this->atividades;
		foreach ($selectedAtivs as $ativ) {
			$atividadeselecionada = Atividade::model()->findByPk($ativ);
			if ($atividadeselecionada->eletivo == false)
				$countnoteletiva++;
			//aproveito aqui para verificar se todas as atividades são do evento selecionado. Um safado pode submeter um post com atividades de outros evento.
			if ($atividadeselecionada->id_evento != $this->id_evento)
				$this->addError($atribbute, 'O que você está tentando fazer ? COD=HackAtividadeforadoEvento');
		}
		if ( $countnoteletiva != count($naoeletivas) )
			$this->addError($atribbute,'Você  desmarcou alguma atividade "Indicada". Todas atividades indicadas necessitam estar marcadas');
	}


    public function checkMultihorario($atribbute)
    {
		if ($this->hasErrors())
			return;
        if ($this->atividades !=null)
        {
            $str = implode (",", $this->atividades);
            $criteria = Yii::app()->db->createCommand();
            $result=$criteria->select ('*')
            ->from ('(select tema, count(*) as qtdei from atividade where id in ('.$str.'
            ) and multihorario=true group by tema)as t')
            ->leftjoin('(select tema, count(*) as qtdet  from atividade where multihorario=true
            group by tema ) as tu ', 't.tema=tu.tema ')
            ->where('t.qtdei != tu.qtdet')
            ->queryall();
            if ($result != null )
            {
                $this->addError($atribbute,'Para realizar a atividade '.$result[0]['tema'].', você precisa escolher todos os '.$result[0]['qtdet']. ' horários');
            }
        } 
    }
    
    public function checkDupla($atribbute)
    {
		if ($this->hasErrors())
			return;
        $dupla = Inscricao::model()->findByAttributes(array('id_evento'=>$this->id_evento,'cpf_dadospessoais'=>$this->cpf_dadospessoais));
		if ($dupla!=null && Inscricao::extractPkValue($dupla) != $this->id)
		{
			$n_insc=Inscricao::extractPkValue($dupla);
			$this->addError($atribbute,"$n_insc-Inscrição no evento já realizada - Caso queira adicionar atividades, altere a inscrição pelo link abaixo");
		}
    }
	public function relations() {
		return array(
			'idEvento' => array(self::BELONGS_TO, 'Evento', 'id_evento'),
			'cpfDadospessoais' => array(self::BELONGS_TO, 'DadosPessoais', 'cpf_dadospessoais'),
			'atividades' => array(self::MANY_MANY, 'Atividade', 'inscricaoatividade(id_inscricao, id_atividade)'),
		);
	}

	public function pivotModels() {
		return array(
			'atividades' => 'Inscricaoatividade',
		);
	}

	public function attributeLabels() {
		return array(
			'id' => Yii::t('app', 'Nº Inscricao'),
			'id_evento' => null,
			'cpf_dadospessoais' => null,
			'idEvento' => null,
			'cpfDadospessoais' => null,
			'atividades' => null,
		);
	}

	
	public function search() {
		$criteria = new CDbCriteria;

		$criteria->compare('id', $this->id);
		$criteria->compare('id_evento', $this->id_evento);
        $criteria->compare('cpf_dadospessoais', $this->cpf_dadospessoais, false);
        $criteria->join='LEFT JOIN "DadosPessoais" as u on t.cpf_dadospessoais=u.cpf';
        $criteria->order='unaccent_string(u.nome)';

		return new CActiveDataProvider($this, array(
			'criteria' => $criteria,
		));
	}
}